<?php
require_once __DIR__.'/../config/bootstrap.php'; require_role('docente');
$uid=(int)current_user()['id']; $today=date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??''; $pid=(int)($_POST['plazo_id']??0); $unitId=(int)($_POST['unidad_id']??0);
 // Permite al docente iniciar el registro de asistencia solo para una unidad que tiene asignada.
 if($action==='open_attendance'){
  $classDate=$_POST['fecha']??$today;
  if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$classDate)){flash('error','Fecha inválida.');redirect('index.php');}
  $check=$pdo->prepare('SELECT u.id FROM asignaciones_docentes ad JOIN unidades_didacticas u ON u.id=ad.unidad_id WHERE ad.docente_id=? AND u.id=? AND u.activa=1');
  $check->execute([$uid,$unitId]);
  if(!$check->fetch()){flash('error','No tienes asignada esa unidad didáctica.');redirect('index.php');}
  $existing=$pdo->prepare("SELECT id FROM plazos_registro WHERE unidad_id=? AND docente_id=? AND fecha_clase=? AND tipo='asistencia'");
  $existing->execute([$unitId,$uid,$classDate]);
  if($existing->fetch()){flash('error','Ya existe un registro de asistencia para esa fecha. Selecciona la unidad y la fecha para abrirlo.');redirect('index.php?unidad_id='.$unitId.'&fecha='.urlencode($classDate));}
  $now=new DateTimeImmutable('now'); $due=$now->modify('+24 hours');
  $create=$pdo->prepare("INSERT INTO plazos_registro(unidad_id,docente_id,fecha_clase,tipo,abierto_en,vencimiento,estado,abierto_por) VALUES(?,?,?,'asistencia',?,?, 'abierto',?)");
  $create->execute([$unitId,$uid,$classDate,$now->format('Y-m-d H:i:s'),$due->format('Y-m-d H:i:s'),$uid]);
  audit($pdo,$uid,'abrir_registro_asistencia','Unidad '.$unitId.'; fecha '.$classDate);
  flash('success','Registro de asistencia habilitado por 24 horas.');redirect('index.php?unidad_id='.$unitId.'&fecha='.urlencode($classDate));
 }
 $q=$pdo->prepare("SELECT p.*,u.carrera_id,u.modulo_num,u.ciclo_num FROM plazos_registro p JOIN unidades_didacticas u ON u.id=p.unidad_id JOIN asignaciones_docentes ad ON ad.unidad_id=u.id AND ad.docente_id=p.docente_id WHERE p.id=? AND p.docente_id=? AND ad.docente_id=? AND u.id=?");
 $q->execute([$pid,$uid,$uid,$unitId]); $p=$q->fetch();
 if(!$p){flash('error','El plazo o la asignación no son válidos.');redirect('index.php');}
 if(!in_array($p['estado'],['abierto','reabierto'],true)||strtotime($p['vencimiento'])<time()){flash('error','El plazo está cerrado o vencido. Solicita una reapertura al administrador.');redirect('index.php?unidad_id='.$unitId.'&fecha='.urlencode($p['fecha_clase']));}
 $q=$pdo->prepare("SELECT us.id FROM matriculas m JOIN usuarios us ON us.id=m.alumno_id WHERE m.estado='activa' AND us.rol='alumno' AND us.estado='activo' AND m.carrera_id=? AND m.modulo_num=? AND m.ciclo_num=?"); $q->execute([$p['carrera_id'],$p['modulo_num'],$p['ciclo_num']]); $studentIds=array_map('intval',array_column($q->fetchAll(),'id'));
 try{$pdo->beginTransaction();
  if($action==='attendance' && $p['tipo']==='asistencia'){
   $states=$_POST['estado']??[]; $save=$pdo->prepare('INSERT INTO asistencias(plazo_id,alumno_id,estado,registrado_por) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE estado=VALUES(estado),registrado_por=VALUES(registrado_por),actualizado_en=CURRENT_TIMESTAMP');
   foreach($studentIds as $sid){$v=$states[$sid]??'';if(!in_array($v,['presente','ausente','tardanza'],true))throw new RuntimeException('Selecciona un estado válido para cada alumno.');$save->execute([$pid,$sid,$v,$uid]);}
   audit($pdo,$uid,'guardar_asistencias','Plazo '.$pid);$pdo->commit();flash('success','Asistencias guardadas correctamente.');
  }elseif($action==='grades' && $p['tipo']==='notas'){
   $concept=trim($_POST['concepto']??'');$grades=$_POST['nota']??[];if($concept===''||mb_strlen($concept)>100)throw new RuntimeException('Indica el concepto de evaluación.');
   $save=$pdo->prepare('INSERT INTO calificaciones(plazo_id,alumno_id,concepto,nota,registrado_por) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE nota=VALUES(nota),registrado_por=VALUES(registrado_por),actualizado_en=CURRENT_TIMESTAMP');
   foreach($studentIds as $sid){if(!isset($grades[$sid])||!is_numeric($grades[$sid])||(float)$grades[$sid]<0||(float)$grades[$sid]>20)throw new RuntimeException('Todas las notas deben estar entre 0 y 20.');$save->execute([$pid,$sid,$concept,(float)$grades[$sid],$uid]);}
   audit($pdo,$uid,'guardar_calificaciones','Plazo '.$pid.'; '.$concept);$pdo->commit();flash('success','Calificaciones guardadas correctamente.');
  }else throw new RuntimeException('La operación no coincide con el tipo de plazo.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar. Revisa los datos e inténtalo nuevamente.');}
 redirect('index.php?unidad_id='.$unitId.'&fecha='.urlencode($p['fecha_clase']));
}
$q=$pdo->prepare("SELECT u.*,c.nombre carrera FROM asignaciones_docentes ad JOIN unidades_didacticas u ON u.id=ad.unidad_id JOIN carreras c ON c.id=u.carrera_id WHERE ad.docente_id=? AND u.activa=1 ORDER BY c.nombre,u.modulo_num,u.ciclo_num,u.nombre");$q->execute([$uid]);$units=$q->fetchAll();
$selected=(int)($_GET['unidad_id']??0);$date=$_GET['fecha']??$today;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=$today;$unit=null;foreach($units as $u)if((int)$u['id']===$selected)$unit=$u;if(!$unit&&$units){$unit=$units[0];$selected=(int)$unit['id'];}
$plazos=[];$students=[];$attendance=[];$grades=[];$schedule=[];
if($unit){$q=$pdo->prepare('SELECT * FROM plazos_registro WHERE unidad_id=? AND docente_id=? AND fecha_clase=?');$q->execute([$selected,$uid,$date]);$plazos=$q->fetchAll();$q=$pdo->prepare("SELECT us.id,us.nombres,us.apellidos,us.dni FROM matriculas m JOIN usuarios us ON us.id=m.alumno_id WHERE m.estado='activa' AND us.rol='alumno' AND us.estado='activo' AND m.carrera_id=? AND m.modulo_num=? AND m.ciclo_num=? ORDER BY us.apellidos,us.nombres");$q->execute([$unit['carrera_id'],$unit['modulo_num'],$unit['ciclo_num']]);$students=$q->fetchAll();foreach($plazos as $p){if($p['tipo']==='asistencia'){$q=$pdo->prepare('SELECT alumno_id,estado FROM asistencias WHERE plazo_id=?');$q->execute([$p['id']]);foreach($q->fetchAll() as $r)$attendance[(int)$r['alumno_id']]=$r['estado'];}else{$q=$pdo->prepare('SELECT alumno_id,concepto,nota FROM calificaciones WHERE plazo_id=?');$q->execute([$p['id']]);foreach($q->fetchAll() as $r)$grades[$r['concepto']][(int)$r['alumno_id']]=$r['nota'];}}}
$q=$pdo->prepare('SELECT h.*,u.nombre unidad,c.nombre carrera FROM horarios h JOIN unidades_didacticas u ON u.id=h.unidad_id JOIN carreras c ON c.id=h.carrera_id WHERE h.docente_id=? ORDER BY h.dia_semana,h.hora_inicio');$q->execute([$uid]);$schedule=$q->fetchAll();
$pageTitle='Panel docente';$assetPrefix='../';require __DIR__.'/../includes/header.php';
?>
<div class="dashboard-head"><div><div class="eyebrow">ESPACIO DOCENTE</div><h1>Hola, <?=h(current_user()['nombre']??'Docente')?></h1><p class="muted">Registra y consulta asistencias y calificaciones de tus unidades.</p></div><span class="status success">Docente</span></div>
<section class="panel"><h2>Seleccionar unidad y fecha</h2><form method="get" class="form-grid"><div class="field"><label for="unidad_id">Unidad didáctica</label><select name="unidad_id" id="unidad_id" required><?php foreach($units as $u):?><option value="<?=$u['id']?>" <?=((int)$u['id']===$selected?'selected':'')?>><?=h($u['carrera'].' · M'.$u['modulo_num'].' C'.$u['ciclo_num'].' · '.$u['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label for="fecha">Fecha de clase</label><input type="date" name="fecha" id="fecha" value="<?=h($date)?>" required></div><div class="field full"><button class="btn primary">Consultar grupo</button></div></form><?php if(!$units):?><p class="muted">No tienes unidades asignadas. Solicita al administrador que te asigne una.</p><?php endif;?></section>
<section class="panel"><h2>Mis horarios</h2><?php if(!$schedule):?><p class="muted">Todavía no tienes horarios asignados.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Día</th><th>Hora</th><th>Unidad</th><th>Grupo</th><th>Aula</th></tr></thead><tbody><?php foreach($schedule as $r):?><tr><td><?=h([1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'][(int)$r['dia_semana']]??'')?></td><td><?=h(substr($r['hora_inicio'],0,5).'–'.substr($r['hora_fin'],0,5))?></td><td><?=h($r['unidad'])?></td><td><?=h($r['carrera'].' · M'.$r['modulo_num'].' C'.$r['ciclo_num'])?></td><td><?=h($r['aula'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($unit): foreach(['asistencia'=>'Registro de asistencias','notas'=>'Registro de calificaciones'] as $type=>$title):$deadline=null;foreach($plazos as $p)if($p['tipo']===$type)$deadline=$p;?><section class="panel"><h2><?=h($title)?></h2><?php if(!$deadline):?><?php if($type==='asistencia'):?><p class="muted">Todavía no has abierto el registro de asistencia para esta unidad y fecha.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="open_attendance"><input type="hidden" name="unidad_id" value="<?=$selected?>"><input type="hidden" name="fecha" value="<?=h($date)?>"><button class="btn primary" type="submit">Habilitar registro de asistencia</button></form><?php else:?><p class="muted">El administrador debe abrir un plazo de tipo «<?=h($type)?>» para esta unidad y fecha.</p><?php endif;?><?php elseif(!$students):?><p class="muted">No hay alumnos activos matriculados en este grupo.</p><?php else:$open=in_array($deadline['estado'],['abierto','reabierto'],true)&&strtotime($deadline['vencimiento'])>=time();?><p class="muted">Fecha <?=h($date)?> · Vencimiento <?=h($deadline['vencimiento'])?> · <?=$open?'Registro habilitado':'Plazo cerrado o vencido'?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="<?=$type==='asistencia'?'attendance':'grades'?>"><input type="hidden" name="plazo_id" value="<?=$deadline['id']?>"><input type="hidden" name="unidad_id" value="<?=$selected?>"><?php if($type==='notas'):?><div class="field"><label for="concepto">Evaluación (por ejemplo, Práctica 1)</label><input id="concepto" name="concepto" maxlength="100" required <?=!$open?'disabled':''?>></div><?php endif;?><div class="table-wrap"><table><thead><tr><th>DNI</th><th>Alumno</th><th><?=$type==='asistencia'?'Estado':'Nota (0–20)'?></th></tr></thead><tbody><?php foreach($students as $st):?><tr><td><?=h($st['dni']?:'—')?></td><td><?=h($st['apellidos'].', '.$st['nombres'])?></td><td><?php if($type==='asistencia'):$val=$attendance[(int)$st['id']]??'presente';?><select name="estado[<?=$st['id']?>]" required <?=!$open?'disabled':''?>><?php foreach(['presente'=>'Presente','tardanza'=>'Tardanza','ausente'=>'Falta'] as $v=>$label):?><option value="<?=$v?>" <?=$val===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><?php else:?><input type="number" name="nota[<?=$st['id']?>]" min="0" max="20" step="0.01" required <?=!$open?'disabled':''?> value="<?=h($grades['__ultimo__'][(int)$st['id']]??'')?>"><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if($open):?><button class="btn primary" type="submit">Guardar <?=$type==='asistencia'?'asistencias':'calificaciones'?></button><?php endif;?></form><?php endif;?>
<?php if($type==='notas'&&$deadline):$q=$pdo->prepare('SELECT c.concepto,us.nombres,us.apellidos,c.nota FROM calificaciones c JOIN usuarios us ON us.id=c.alumno_id WHERE c.plazo_id=? ORDER BY c.concepto,us.apellidos');$q->execute([$deadline['id']]);$rows=$q->fetchAll();if($rows):?><h3>Notas registradas</h3><div class="table-wrap"><table><thead><tr><th>Evaluación</th><th>Alumno</th><th>Nota</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['concepto'])?></td><td><?=h($r['apellidos'].', '.$r['nombres'])?></td><td><?=h($r['nota'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;endif;?></section><?php endforeach;endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
